148:   constructor(database: ReadingListDatabase, listsDao: ReadingListsDao, pagesDao: ReadingListPagesDao,
149:     preferences: SavedPreferences, environment: SavedEnvironment, session: SavedSession,
150:     mediaStatus: ArticleMediaStatus) {
151:     this.database = database;
152:     this.listsDao = listsDao;
153:     this.pagesDao = pagesDao;
154:     this.preferences = preferences;
155:     this.environment = environment;
156:     this.session = session;
157:     this.mediaStatus = mediaStatus;
158:     this.state = new SavedUiState();
159:     this.listsWithPages = listsDao.observeListsWithPages();
160:     this.state.availableTabs = [TAB_ALL_ARTICLES, TAB_COLLECTIONS];
161:     this.state.articleSortChoices = copyNumbers(ARTICLE_SORT_CHOICES);
162:     this.state.collectionSortChoices = copyNumbers(COLLECTION_SORT_CHOICES);
163:     this.state.searchDebounceMillis = SEARCH_DEBOUNCE_MILLIS;
164:     this.state.selectedTab = TAB_ALL_ARTICLES;
165:     this.state.selectedArticleFilter = ARTICLE_FILTER_ALL_ARTICLES;
166:     this.state.articleSortMode = SORT_BY_NAME_ASC;
167:     this.state.collectionSortMode = SORT_BY_NAME_ASC;
