172:   /* -------------------------------------------------------------------- */
173:   /* Wiring                                                                 */
174:   /* -------------------------------------------------------------------- */
175: 
176:   /** Subscribes to the reactive projections; database changes drive updates. */
177:   start(): void {
178:     this.listsWithPages.collect((_: RoomListWithPages[]): void => {
179:       this.onDatabaseChanged();
180:     });
181:     this.pagesDao.observeActivePages().collect((): void => {
182:       this.onDatabaseChanged();
183:     });
184:     this.state.account = this.session.snapshot();
185:     this.state.readingListSyncEnabled = this.session.isSyncEnabled();
186:     this.onDatabaseChanged();
187:   }
188: 
189:   observe(observer: UiStateObserver): void {
190:     this.observers.push(observer);
191:   }
192: 
193:   currentState(): SavedUiState {
194:     return this.state;
195:   }
196: 
197:   private notify(): void {
198:     for (let index = 0; index < this.observers.length; index++) {
199:       this.observers[index](this.state);
200:     }
201:   }
