203:   /**
204:    * Called for every database change. The projection is rebuilt from the
205:    * tables, which is what keeps the All articles and Collections views, the
206:    * collection counters and the save sheet consistent with each other.
207:    */
208:   private onDatabaseChanged(): void {
209:     this.state.articleRows = this.projectArticleRows();
210:     this.state.collectionRows = this.projectCollectionRows();
211:     this.state.visibleArticleRowIds = this.state.articleRowIds();
212:     this.state.visibleCollectionRowIds = this.state.collectionRowIds();
213:     this.dropSelectionOfMissingRows();
214:     this.refreshMediaStatus();
215:     this.state.pendingDeletionArticleIds = this.queuedArticleIds();
216:     this.state.pendingDeletionCollectionIds = this.queuedCollectionIds();
217:     this.state.undoAvailable = this.pendingUndo !== null && !this.pendingUndo.isEmpty();
218:     this.state.emptyState = this.resolveEmptyState();
219:     this.state.menuActions = this.resolveMenuActions();
220:     this.state.badgeCount = this.localChangeCount;
221:     this.resolveOnboarding();
222:     this.notify();
223:   }
224: 
225:   private recompute(): void {
226:     this.onDatabaseChanged();
227:   }
