349:   /* -------------------------------------------------------------------- */
350:   /* Surface lifecycle                                                      */
351:   /* -------------------------------------------------------------------- */
352: 
353:   /** The Saved surface always opens on the deduplicated All articles view. */
354:   async openSavedSurface(): Promise<void> {
355:     this.surfaceOpen = true;
356:     this.state.selectedTab = TAB_ALL_ARTICLES;
357:     this.state.isLoading = true;
358:     this.notify();
359:     this.state.isLoading = false;
360:     this.state.emptyState = EMPTY_STATE_NONE;
361:     this.recompute();
362:   }
