374:   /* -------------------------------------------------------------------- */
375:   /* Tabs                                                                   */
376:   /* -------------------------------------------------------------------- */
377: 
378:   async selectSavedTab(tab: string): Promise<void> {
379:     if (!isSavedTab(tab) || tab === this.state.selectedTab) {
380:       if (isSavedTab(tab)) {
381:         this.recompute();
382:       }
383:       return;
384:     }
385:     // The reader keeps the text they typed; only the scope it applies to moves.
386:     this.flushPendingSearch();
387:     this.state.selectedTab = tab;
388:     if (tab !== TAB_ALL_ARTICLES) {
389:       // Filtering to "only in the default collection" is an All articles idea.
390:       this.state.selectedArticleFilter = ARTICLE_FILTER_ALL_ARTICLES;
391:     }
392:     await this.preferences.setLastTab(tab);
393:     this.recompute();
394:   }
395: 
396:   /* -------------------------------------------------------------------- */
397:   /* Search                                                                 */
398:   /* -------------------------------------------------------------------- */
399: 
400:   /**
401:    * Entry point of the debounced search field.
402:    *
403:    * A non empty query always waits for the full production debounce window;
404:    * clearing the query is applied immediately because there is nothing left to
405:    * narrow down.
406:    */
407:   async enterSavedSearchQuery(query: string, elapsedMillis: number): Promise<void> {
408:     this.state.pendingSearchQuery = query;
409:     this.cancelPendingSearch();
410:     if (query.length === 0) {
411:       this.state.searchQuery = '';
412:       this.state.isSearchPending = false;
413:       this.recompute();
414:       return;
415:     }
416:     const debounce = this.debounceMillis();
417:     const elapsed = elapsedMillis > 0 ? elapsedMillis : 0;
418:     if (elapsed >= debounce) {
419:       this.applySearchQuery(query);
420:       return;
421:     }
422:     this.state.isSearchPending = true;
423:     this.notify();
424:     this.searchTimerId = setTimeout((): void => {
425:       this.searchTimerId = -1;
426:       this.applySearchQuery(query);
427:     }, debounce - elapsed);
428:   }
429: 
430:   private debounceMillis(): number {
431:     return this.state.searchDebounceMillis > 0 ? this.state.searchDebounceMillis : SEARCH_DEBOUNCE_MILLIS;
432:   }
433: 
434:   private applySearchQuery(query: string): void {
435:     this.state.searchQuery = query;
436:     this.state.pendingSearchQuery = query;
437:     this.state.isSearchPending = false;
438:     this.recompute();
439:   }
440: 
441:   private flushPendingSearch(): void {
442:     if (this.searchTimerId >= 0) {
443:       this.cancelPendingSearch();
444:       if (this.state.pendingSearchQuery.length > 0) {
445:         this.applySearchQuery(this.state.pendingSearchQuery);
446:       }
447:     }
448:   }
449: 
450:   private cancelPendingSearch(): void {
451:     if (this.searchTimerId >= 0) {
452:       clearTimeout(this.searchTimerId);
453:       this.searchTimerId = -1;
454:     }
455:     this.state.isSearchPending = false;
456:   }
