458:   /* -------------------------------------------------------------------- */
459:   /* Filter and sort                                                        */
460:   /* -------------------------------------------------------------------- */
461: 
462:   async selectArticleFilter(filter: string): Promise<void> {
463:     if (!isArticleFilter(filter)) {
464:       return;
465:     }
466:     if (this.state.selectedTab !== TAB_ALL_ARTICLES) {
467:       this.state.selectedTab = TAB_ALL_ARTICLES;
468:     }
469:     this.state.selectedArticleFilter = filter;
470:     this.recompute();
471:   }
