473:   /** Sort preferences are stored per view, so switching tabs keeps both. */
474:   async selectSortMode(mode: number): Promise<void> {
475:     if (this.state.selectedTab === TAB_COLLECTIONS) {
476:       if (!isSortMode(mode, COLLECTION_SORT_CHOICES)) {
477:         return;
478:       }
479:       this.state.collectionSortMode = mode;
480:       await this.preferences.setCollectionSortMode(mode);
481:     } else {
482:       if (!isSortMode(mode, ARTICLE_SORT_CHOICES)) {
483:         return;
484:       }
485:       this.state.articleSortMode = mode;
486:       await this.preferences.setArticleSortMode(mode);
487:     }
488:     this.recompute();
489:   }
