491:   /* -------------------------------------------------------------------- */
492:   /* Selection                                                              */
493:   /* -------------------------------------------------------------------- */
494: 
495:   async enterSelectionMode(): Promise<void> {
496:     this.state.selectionEnabled = true;
497:     this.recompute();
498:   }
499: 
500:   async exitSelectionMode(): Promise<void> {
501:     this.state.selectionEnabled = false;
502:     this.state.selectedRowIds = [];
503:     this.recompute();
504:   }
505: 
506:   async toggleRowSelection(rowId: number): Promise<void> {
507:     if (!this.state.selectionEnabled) {
508:       this.state.selectionEnabled = true;
509:     }
510:     if (this.state.selectedRowIds.indexOf(rowId) >= 0) {
511:       this.state.selectedRowIds = this.state.selectedRowIds.filter((id: number): boolean => id !== rowId);
512:     } else {
513:       const next = copyNumbers(this.state.selectedRowIds);
514:       next.push(rowId);
515:       this.state.selectedRowIds = next;
516:     }
517:     this.recompute();
518:   }
519: 
520:   async selectNone(): Promise<void> {
521:     this.state.selectedRowIds = [];
522:     this.recompute();
523:   }
