525:   /**
526:    * Selects exactly the rows that are on screen right now. Because the rows are
527:    * already deduplicated, every logical article contributes a single id and
528:    * rows that the current filter hides are never selected.
529:    */
530:   async selectAllVisibleRows(): Promise<void> {
531:     this.state.selectionEnabled = true;
532:     const visible = this.state.selectedTab === TAB_COLLECTIONS
533:       ? this.state.visibleCollectionRowIds
534:       : this.state.visibleArticleRowIds;
535:     this.state.selectedRowIds = copyNumbers(visible);
536:     this.recompute();
537:   }
