543:   /* -------------------------------------------------------------------- */
544:   /* Save / unsave                                                          */
545:   /* -------------------------------------------------------------------- */
546: 
547:   /**
548:    * Opens the save-article sheet for an article.
549:    *
550:    * Redirect metadata is resolved first, but only when the device can reach the
551:    * API: an offline or failing lookup leaves the original language and API title
552:    * as the identity that gets persisted. Opening the sheet always guarantees the
553:    * article is saved.
554:    */
555:   async openSaveArticleSheet(): Promise<void> {
556:     const requested = this.takePendingPageTitle();
557:     const metadata = await this.environment.resolveRedirectMetadata(requested);
558:     let identity = requested;
559:     if (metadata !== undefined) {
560:       identity = new PageTitle(requested.languageCode, metadata.to, '');
561:     }
562: 
563:     const saved = this.pagesDao.saveToDefaultCollection(identity);
564:     if (!saved.applied) {
565:       this.showFeedback(saved.message, FEEDBACK_SEVERITY_WARNING, FEEDBACK_ACTION_DISMISS);
566:     } else {
567:       this.markLocalChange(1);
568:     }
569: 
570:     const sheet = new SaveArticleSheetState(identity);
571:     sheet.isSaved = this.pagesDao.isSaved(identity.identity);
572:     this.state.saveSheet = sheet;
573:     this.refreshSheetOptions(sheet);
574:     this.recompute();
575:   }
576: 
577:   async dismissSaveArticleSheet(): Promise<void> {
578:     this.state.saveSheet = null;
579:     this.queuedToggle = null;
580:     this.notify();
581:   }
