583:   /** Applies the checkbox of a collection row rendered inside the sheet. */
584:   async toggleSheetCollection(listId: number): Promise<void> {
585:     const sheet = this.state.saveSheet;
586:     if (sheet === null) {
587:       return;
588:     }
589:     const change = this.pagesDao.toggleCollection(listId, PageTitle.fromIdentity(sheet.article));
590:     this.reportMembershipChange(change);
591:   }
