593:   /**
594:    * Removes the article from every collection. Confirmation is required as soon
595:    * as one containing collection is user created.
596:    */
597:   async requestUnsave(): Promise<void> {
598:     const sheet = this.state.saveSheet;
599:     if (sheet === null) {
600:       return;
601:     }
602:     const named = this.pagesDao.nonDefaultMembershipsOf(sheet.article);
603:     if (named.length > 0) {
604:       sheet.pendingConfirmation = true;
605:       sheet.confirmationCollections = copyStrings(named);
606:       this.refreshSheetOptions(sheet);
607:       this.notify();
608:       return;
609:     }
610:     await this.performUnsave(sheet.article);
611:   }
612: 
613:   /**
614:    * Cancels the destructive confirmation. No membership is touched: the
615:    * confirmation only ever asked a question.
616:    */
617:   async cancelUnsaveConfirmation(): Promise<void> {
618:     const sheet = this.state.saveSheet;
619:     if (sheet === null || !sheet.pendingConfirmation) {
620:       return;
621:     }
622:     sheet.pendingConfirmation = false;
623:     sheet.confirmationCollections = [];
624:     this.refreshSheetOptions(sheet);
625:     this.notify();
626:   }
627: 
628:   /** Confirms the destructive path: every membership goes away. */
629:   async confirmUnsave(): Promise<void> {
630:     const sheet = this.state.saveSheet;
631:     if (sheet === null || !sheet.pendingConfirmation) {
632:       return;
633:     }
634:     const identity = sheet.article;
635:     sheet.pendingConfirmation = false;
636:     sheet.confirmationCollections = [];
637:     await this.performUnsave(identity);
638:   }
