725:   private reportMembershipChange(change: MembershipChange): boolean {
726:     if (!change.applied && change.reason === 'MISSING_COLLECTION') {
727:       this.showFeedback('That collection is no longer available', FEEDBACK_SEVERITY_WARNING,
728:         FEEDBACK_ACTION_DISMISS);
729:       this.refreshSheetOptions(this.state.saveSheet);
730:       this.notify();
731:       return false;
732:     }
733:     if (!change.applied) {
734:       this.showFeedback(change.message, FEEDBACK_SEVERITY_WARNING, FEEDBACK_ACTION_DISMISS);
735:       const sheet = this.state.saveSheet;
736:       if (sheet !== null) {
737:         sheet.limitMessage = change.message;
738:       }
739:       this.refreshSheetOptions(sheet);
740:       this.notify();
741:       return false;
742:     }
743:     if (change.reason === 'REMOVED') {
744:       this.markLocalChange(-1);
745:     } else {
746:       this.markLocalChange(1);
747:     }
748:     this.refreshSheetOptions(this.state.saveSheet);
749:     this.recompute();
750:     return true;
751:   }
