764:     const undo = new PendingUndo();
765:     const rows = this.state.selectedArticleRows();
766:     for (let index = 0; index < rows.length; index++) {
767:       const identity = rows[index].article;
768:       undo.articleIdentities.push(identity);
769:       const pageIds = this.pagesDao.queueForDeletion([identity]);
770:       for (let inner = 0; inner < pageIds.length; inner++) {
771:         if (undo.articlePageIds.indexOf(pageIds[inner]) < 0) {
772:           undo.articlePageIds.push(pageIds[inner]);
773:         }
774:       }
775:     }
776:     this.pendingUndo = undo.isEmpty() ? null : undo;
777:     this.state.selectedRowIds = [];
