841:   /**
842:    * The undo window stays open until the reader performs another destructive
843:    * action; after that the queued rows are removed for good.
844:    */
845:   private commitPendingUndo(): void {
846:     const undo = this.pendingUndo;
847:     if (undo === null) {
848:       return;
849:     }
850:     if (undo.articlePageIds.length > 0) {
851:       this.database.hardDeletePages(undo.articlePageIds);
852:     }
853:     for (let index = 0; index < undo.collectionIds.length; index++) {
854:       this.listsDao.deleteCollection(undo.collectionIds[index]);
855:     }
856:     this.pendingUndo = null;
857:   }
