859:   private queuedArticleIds(): number[] {
860:     if (this.pendingUndo !== null) {
861:       return copyNumbers(this.pendingUndo.articlePageIds);
862:     }
863:     const queued = this.database.queuedPages();
864:     const ids: number[] = [];
865:     for (let index = 0; index < queued.length; index++) {
866:       ids.push(queued[index].id);
867:     }
868:     return ids;
869:   }
870: 
871:   private queuedCollectionIds(): number[] {
872:     const ids: number[] = [];
873:     const projected = this.listsWithPages.getValue();
874:     for (let index = 0; index < projected.length; index++) {
875:       const total = this.database.pagesForList(projected[index].list.id).length;
876:       if (total > projected[index].pages.length) {
877:         ids.push(projected[index].list.id);
878:       }
879:     }
880:     return ids;
881:   }
