914:   private resolveOnboarding(): void {
915:     if (this.session.sharedCollectionCount() > 0 && this.state.sharedCollectionTitle.length > 0) {
916:       this.state.onboarding = ONBOARDING_SHARED_COLLECTION;
917:       return;
