920:       this.state.onboarding = ONBOARDING_LOGIN_REMINDER;
921:       return;
922:     }
923:     if (this.session.isSyncEnabled() && this.session.isSyncEligible()
924:       && this.state.articleRows.length > 0 && this.state.syncCompletedCount === 0) {
925:       this.state.onboarding = ONBOARDING_SYNC_REMINDER;
926:       return;
927:     }
