931:   /* -------------------------------------------------------------------- */
932:   /* Pull to refresh                                                        */
933:   /* -------------------------------------------------------------------- */
934: 
935:   /**
936:    * Pull to refresh.
937:    *
938:    * An ineligible account returns to idle immediately and shows a login prompt
939:    * without dispatching any synchronisation. An eligible account starts
940:    * synchronisation and stays refreshing until the sync completion event
941:    * arrives; membership changes applied in the meantime are projected right
942:    * away, even while the spinner is still running.
943:    */
944:   async pullToRefresh(): Promise<void> {
945:     this.state.isRefreshing = true;
946:     this.state.lastRefreshOutcome = REFRESH_OUTCOME_REFRESHING;
947:     this.state.loginPromptVisible = false;
948:     this.state.refreshAttempts = this.state.refreshAttempts + 1;
949:     this.notify();
950: 
951:     if (!this.session.isSyncEligible()) {
952:       this.state.isRefreshing = false;
953:       this.state.syncInFlight = false;
954:       this.state.loginPromptVisible = true;
955:       this.state.lastRefreshOutcome = REFRESH_OUTCOME_LOGIN_PROMPT;
956:       this.resolveOnboarding();
957:       this.notify();
958:       return;
959:     }
960: 
961:     this.state.syncInFlight = true;
962:     const request = new ReadingListSyncRequest(this.localChangeCount > 0, true, this.state.refreshAttempts);
963:     const response = await this.environment.startReadingListSync(request);
964:     this.state.syncStartedCount = this.state.syncStartedCount + 1;
965:     if (!response.completed) {
966:       this.state.syncInFlight = false;
967:       this.state.isRefreshing = false;
968:       this.state.lastRefreshOutcome = REFRESH_OUTCOME_SYNC_FAILED;
969:       this.showFeedback('Reading list sync failed: ' + response.exception, FEEDBACK_SEVERITY_ERROR,
970:         FEEDBACK_ACTION_DISMISS);
971:       this.notify();
972:       return;
973:     }
974: 
975:     this.state.lastRefreshOutcome = REFRESH_OUTCOME_SYNC_STARTED;
976:     this.applyRemoteSync();
977:     this.notify();
978: 
979:     if (this.syncCompletion === SYNC_COMPLETION_HELD) {
980:       return;
981:     }
982:     await this.onReadingListSyncEvent(SYNC_EVENT_COMPLETED);
983:   }
984: 
985:   /** Applies the memberships synchronisation pushed before completing. */
986:   private applyRemoteSync(): void {
987:     const additions = this.remoteSyncAdds;
988:     this.remoteSyncAdds = [];
989:     for (let index = 0; index < additions.length; index++) {
990:       const addition = additions[index];
991:       const pageTitle = PageTitle.fromIdentity(addition.article);
992:       this.pagesDao.saveToDefaultCollection(pageTitle);
993:       for (let inner = 0; inner < addition.collections.length; inner++) {
994:         const list = this.listsDao.listByTitle(addition.collections[inner]);
995:         if (list !== undefined) {
996:           this.pagesDao.addToCollection(list.id, pageTitle);
997:         }
998:       }
999:     }
1000:     if (additions.length > 0) {
1001:       this.recompute();
1002:     }
1003:   }
1004: 
1005:   /** Completion notification of the synchronisation service. */
1006:   async onReadingListSyncEvent(event: string): Promise<void> {
1007:     if (event !== SYNC_EVENT_COMPLETED && event !== SYNC_EVENT_FAILED) {
1008:       return;
1009:     }
1010:     this.state.syncInFlight = false;
1011:     this.state.isRefreshing = false;
1012:     if (event === SYNC_EVENT_COMPLETED) {
1013:       this.state.syncCompletedCount = this.state.syncCompletedCount + 1;
1014:       this.state.lastRefreshOutcome = REFRESH_OUTCOME_SYNC_COMPLETED;
1015:       this.localChangeCount = 0;
1016:       await this.environment.reportSyncEvent(true, '', [TAB_ALL_ARTICLES, TAB_COLLECTIONS]);
1017:     } else {
1018:       this.state.lastRefreshOutcome = REFRESH_OUTCOME_SYNC_FAILED;
1019:       await this.environment.reportSyncEvent(false, 'sync_failed', [TAB_ALL_ARTICLES, TAB_COLLECTIONS]);
1020:     }
1021:     this.resolveOnboarding();
1022:     this.recompute();
1023:   }
