1078:   private projectArticleRows(): SavedArticleRow[] {
1079:     const records = this.pagesDao.logicalArticles();
1080:     const defaultTitle = this.pagesDao.defaultTitle();
1081:     const query = SavedTextSearch.prepareQuery(this.state.searchQuery);
1082:     const rows: SavedArticleRow[] = [];
1083:     for (let index = 0; index < records.length; index++) {
1084:       const record: SavedArticleRecord = records[index];
1085:       if (!this.passesArticleFilter(record, defaultTitle)) {
1086:         continue;
1087:       }
1088:       if (query.length > 0 && !this.matchesArticleQuery(record, query)) {
1089:         continue;
1090:       }
1091:       const row = new SavedArticleRow(record.rowId, record.pageTitle, record.collections,
1092:         record.onlyInDefaultCollection(defaultTitle), record.addedAt, record.updatedAt);
1093:       row.isOffline = this.mediaStatus.isOffline(record.identity);
1094:       row.downloadProgress = this.mediaStatus.downloadProgress(record.identity);
1095:       row.selected = this.state.selectedRowIds.indexOf(row.id) >= 0;
1096:       rows.push(row);
1097:     }
1098:     this.sortArticleRows(rows);
1099:     return rows;
1100:   }
1101: 
1102:   /**
1103:    * The filter inspects the complete set of containing collections of the
1104:    * deduplicated article; an article in any named collection is excluded even
1105:    * when the default collection also holds it.
1106:    */
1107:   private passesArticleFilter(record: SavedArticleRecord, defaultTitle: string): boolean {
1108:     if (this.state.selectedArticleFilter === ARTICLE_FILTER_NOT_IN_COLLECTION) {
1109:       return !record.isInNamedCollection(defaultTitle);
1110:     }
1111:     return true;
1112:   }
1113: 
1114:   /**
1115:    * The article view matches on the article itself. Collection titles are only
1116:    * searched on the Collections tab, where they are the row content.
1117:    */
1118:   private matchesArticleQuery(record: SavedArticleRecord, query: string): boolean {
1119:     if (SavedTextSearch.matches(record.pageTitle.displayTitle, query)) {
1120:       return true;
1121:     }
1122:     return SavedTextSearch.matches(record.pageTitle.apiTitle.replace(/_/g, ' '), query);
1123:   }
1124: 
1125:   private sortArticleRows(rows: SavedArticleRow[]): void {
1126:     const mode = this.state.articleSortMode;
1127:     rows.sort((left: SavedArticleRow, right: SavedArticleRow): number => {
1128:       if (mode === SORT_BY_NAME_DESC) {
1129:         return -SavedTextSearch.normalise(right.displayTitle).localeCompare(SavedTextSearch.normalise(left.displayTitle));
1130:       }
1131:       if (mode === SORT_BY_DATE_ADDED) {
1132:         return right.addedAt - left.addedAt;
1133:       }
1134:       if (mode === SORT_BY_DATE_LAST_UPDATED) {
1135:         return right.updatedAt - left.updatedAt;
1136:       }
1137:       return SavedTextSearch.normalise(left.displayTitle).localeCompare(SavedTextSearch.normalise(right.displayTitle));
1138:     });
1139:   }
1140: 
1141:   private projectCollectionRows(): SavedCollectionRow[] {
1142:     const projected = this.listsWithPages.getValue();
1143:     const query = SavedTextSearch.prepareQuery(this.state.searchQuery);
1144:     const rows: SavedCollectionRow[] = [];
1145:     for (let index = 0; index < projected.length; index++) {
1146:       const list = projected[index].list;
1147:       if (list.isDefault) {
1148:         // The default collection is never a user created collection.
1149:         continue;
1150:       }
1151:       if (query.length > 0 && !SavedTextSearch.matches(list.title, query)
1152:         && !SavedTextSearch.matches(list.description, query)) {
1153:         continue;
1154:       }
1155:       const row = new SavedCollectionRow(list.id, list.title, list.description, list.isDefault,
1156:         projected[index].pages.length);
1157:       row.offlineArticleCount = this.countOfflineArticles(projected[index]);
1158:       row.selected = this.state.selectedRowIds.indexOf(row.id) >= 0;
1159:       row.queuedForDeletion = row.articleCount < this.database.pagesForList(list.id).length;
1160:       rows.push(row);
1161:     }
1162:     const mode = this.state.collectionSortMode;
1163:     rows.sort((left: SavedCollectionRow, right: SavedCollectionRow): number => {
1164:       if (mode === SORT_BY_NAME_DESC) {
1165:         return -SavedTextSearch.normalise(right.title).localeCompare(SavedTextSearch.normalise(left.title));
1166:       }
1167:       return SavedTextSearch.normalise(left.title).localeCompare(SavedTextSearch.normalise(right.title));
1168:     });
1169:     return rows;
1170:   }
1171: 
1172:   private countOfflineArticles(withPages: RoomListWithPages): number {
1173:     let total = 0;
1174:     for (let index = 0; index < withPages.pages.length; index++) {
1175:       if (this.mediaStatus.isOffline(withPages.pages[index].identity)) {
1176:         total = total + 1;
1177:       }
1178:     }
1179:     return total;
1180:   }
1181: 
1182:   private refreshSheetOptions(sheet: SaveArticleSheetState | null): void {
1183:     if (sheet === null) {
1184:       return;
1185:     }
1186:     const projected = this.listsWithPages.getValue();
1187:     const options: SaveArticleCollectionOption[] = [];
1188:     for (let index = 0; index < projected.length; index++) {
1189:       const list = projected[index].list;
1190:       const checked = this.pagesDao.membershipsOf(sheet.article).indexOf(list.title) >= 0;
1191:       const option = new SaveArticleCollectionOption(list.id, list.title, list.isDefault, checked);
1192:       if (!checked) {
1193:         const decision = SavedLimitPolicy.canAddArticle(projected[index].pages.length);
1194:         if (!decision.allowed) {
1195:           option.disabled = true;
1196:           option.limitReason = decision.reason;
1197:         }
1198:       }
1199:       options.push(option);
1200:     }
1201:     options.sort((left: SaveArticleCollectionOption, right: SaveArticleCollectionOption): number => {
1202:       if (left.isDefault !== right.isDefault) {
1203:         return left.isDefault ? -1 : 1;
1204:       }
1205:       return SavedTextSearch.normalise(left.title).localeCompare(SavedTextSearch.normalise(right.title));
1206:     });
1207:     sheet.collections = options;
1208:     sheet.isSaved = this.pagesDao.isSaved(sheet.article);
