259:   private static restoreCollections(snapshot: RestoredSavedState, context: RestoredContext,
260:     summary: RestoredSummary): void {
261:     let highestListId = 0;
262:     const specs: RestoredRoomList[] = [];
263: 
264:     const collect = (lists: RestoredRoomList[] | undefined): void => {
265:       if (lists === undefined || lists === null) {
266:         return;
267:       }
268:       for (let index = 0; index < lists.length; index++) {
269:         const spec = lists[index];
270:         specs.push(spec);
271:         const explicitId: number | undefined = spec.id !== undefined && spec.id !== null ? spec.id : undefined;
272:         if (explicitId !== undefined && explicitId > highestListId) {
273:           highestListId = explicitId;
274:         }
275:       }
276:     };
277:     collect(snapshot.roomLists);
278:     collect(snapshot.roomCollections);
279: 
280:     // The default collection always exists, even when the snapshot has none.
281:     let defaultTitle = DEFAULT_COLLECTION_TITLE;
282:     for (let index = 0; index < specs.length; index++) {
283:       const spec = specs[index];
284:       const title: string = spec.title !== undefined && spec.title !== null ? spec.title : '';
285:       if (spec.isDefault === true && title.length > 0) {
286:         defaultTitle = title;
287:         break;
288:       }
289:     }
290:     context.database.reserveListIdAtLeast(highestListId + 1);
291: 
292:     for (let index = 0; index < specs.length; index++) {
293:       const spec = specs[index];
294:       const title: string = spec.title !== undefined && spec.title !== null ? spec.title : '';
295:       if (title.length === 0 || context.listsDao.listByTitle(title) !== undefined) {
296:         continue;
297:       }
298:       const isDefault: boolean = spec.isDefault === true || title === defaultTitle;
299:       const description: string = spec.description !== undefined && spec.description !== null ? spec.description : '';
300:       const now: number = context.database.nextTimestamp();
301:       const explicitId: number | undefined = spec.id !== undefined && spec.id !== null ? spec.id : undefined;
302:       const listId: number = explicitId !== undefined
303:         ? context.database.reserveSpecificListId(explicitId)
304:         : context.database.reserveListId();
305:       context.database.insertList(new RoomListEntity(listId, title, isDefault, description, index, now, now));
306:     }
307: 
308:     const collectionTitles: string[] | undefined = snapshot.collectionTitles;
309:     if (collectionTitles !== undefined && collectionTitles !== null) {
310:       for (let index = 0; index < collectionTitles.length; index++) {
311:         SavedStateRestorer.ensureCollection(collectionTitles[index], false, context);
312:       }
313:     }
314: 
315:     summary.defaultCollectionTitle = context.pagesDao.defaultTitle();
316:   }
