335:   private static restoreMemberships(snapshot: RestoredSavedState, context: RestoredContext,
336:     summary: RestoredSummary): void {
337:     // Reserve every explicit identifier before any automatic one is handed out.
338:     let highestPageId = 0;
339:     const rows: RestoredArticleRow[] = [];
340:     const collectRows = (source: RestoredArticleRow[] | undefined): void => {
341:       if (source === undefined || source === null) {
342:         return;
343:       }
344:       for (let index = 0; index < source.length; index++) {
345:         const row: RestoredArticleRow = toRestoredRow(source[index]);
346:         rows.push(row);
347:         const explicitId: number | undefined = row.id !== undefined && row.id !== null ? row.id : undefined;
348:         if (explicitId !== undefined && explicitId > highestPageId) {
349:           highestPageId = explicitId;
350:         }
351:       }
352:     };
353:     collectRows(snapshot.visibleArticleRows);
354:     collectRows(snapshot.hiddenByFilter);
355: 
356:     // Plain identities listed for the surface are saved articles themselves.
357:     const plainRows: string[] | undefined = snapshot.articleRows;
358:     if (plainRows !== undefined && plainRows !== null) {
359:       for (let index = 0; index < plainRows.length; index++) {
360:         rows.push(new RestoredRowDescriptor(plainRows[index], undefined, undefined));
361:       }
362:     }
363:     context.database.reservePageIdAtLeast(highestPageId + 1);
364: 
365:     // 1. Collections that list their articles.
366:     const specs: RestoredRoomList[] = [];
367:     const roomLists: RestoredRoomList[] | undefined = snapshot.roomLists;
368:     if (roomLists !== undefined && roomLists !== null) {
369:       for (let index = 0; index < roomLists.length; index++) {
370:         specs.push(roomLists[index]);
371:       }
372:     }
373:     for (let index = 0; index < specs.length; index++) {
374:       const spec = specs[index];
375:       const articles: string[] | undefined = spec.articles;
376:       const title: string = spec.title !== undefined && spec.title !== null ? spec.title : '';
377:       if (articles === undefined || articles === null || title.length === 0) {
378:         continue;
379:       }
380:       const list = context.listsDao.listByTitle(title);
381:       if (list === undefined) {
382:         continue;
383:       }
384:       for (let inner = 0; inner < articles.length; inner++) {
385:         SavedStateRestorer.insertMembership(context, list.id, PageTitle.fromIdentity(articles[inner]),
386:           undefined, '');
387:       }
388:     }
389: 
390:     // 2. Explicit identity -> collections map.
391:     SavedStateRestorer.restoreMembershipMap(context, snapshot.articleMemberships, undefined, '', undefined);
392: 
393:     // 3. The article the save sheet is about.
394:     const sheetArticle: string = SavedStateRestorer.resolveSheetArticle(snapshot);
395:     const memberships: string[] | undefined = snapshot.memberships;
396:     if (memberships !== undefined && memberships !== null) {
397:       for (let index = 0; index < memberships.length; index++) {
398:         SavedStateRestorer.ensureCollection(memberships[index], false, context);
399:       }
400:       const list = context.pagesDao.defaultList();
401:       if (sheetArticle.length > 0) {
402:         SavedStateRestorer.insertMembership(context, list.id, PageTitle.fromIdentity(sheetArticle), undefined, '');
403:       }
404:       for (let index = 0; index < memberships.length; index++) {
405:         const title = memberships[index];
406:         if (title === context.pagesDao.defaultTitle()) {
407:           continue;
408:         }
409:         const named = context.listsDao.listByTitle(title);
410:         if (named !== undefined && sheetArticle.length > 0) {
411:           SavedStateRestorer.insertMembership(context, named.id, PageTitle.fromIdentity(sheetArticle), undefined, '');
412:         }
413:       }
414:     }
415: 
416:     // 4. Rows the surface was rendering.
417:     for (let index = 0; index < rows.length; index++) {
418:       SavedStateRestorer.restoreRow(context, rows[index]);
419:     }
420: 
421:     // 5. Rows queued for deletion: they stay persisted but are not projected.
422:     if (snapshot.queuedForDeletion !== undefined && snapshot.queuedForDeletion !== null) {
423:       const queuedIds: number[] = [];
424:       const queuedIdentities: string[] = [];
425:       SavedStateRestorer.restoreMembershipMap(context, snapshot.queuedForDeletion, queuedIds, STATUS_QUEUE_FOR_DELETE,
426:         queuedIdentities);
427:       context.viewModel.seedQueuedDeletion(queuedIdentities, queuedIds);
428:       context.viewModel.seedUndoAvailable(snapshot.undoAvailable !== false);
429:     }
430: 
431:     if (snapshot.undoAvailable === false) {
432:       context.viewModel.seedUndoAvailable(false);
433:     }
434:   }
