459:   private static restoreMembershipMap(context: RestoredContext, map: Record<string, string[]> | undefined,
460:     collectedIds: number[] | undefined, status: string, collectedIdentities: string[] | undefined): void {
461:     if (map === undefined || map === null) {
462:       return;
463:     }
464:     const identities: string[] = Object.keys(map);
465:     for (let index = 0; index < identities.length; index++) {
466:       const identity = identities[index];
467:       const titles: string[] = map[identity];
468:       for (let inner = 0; inner < titles.length; inner++) {
