141:   private static readSortModes(persistence: Record<string, Object>): RestoredSortModes | undefined {
142:     const raw = LegacySavedStore.lookup(persistence, 'persistedSortModes');
143:     if (raw === undefined) {
144:       return LegacySavedStore.lookup(persistence, 'sortModes');
145:     }
146:     const parsed = JSON.parse(JSON.stringify(raw)) as RestoredSortModes;
147:     if (parsed === undefined || parsed === null) {
