153:   private static lookup(bag: Record<string, Object>, key: string): Object | undefined {
154:     const keys: string[] = Object.keys(bag);
155:     for (let index = 0; index < keys.length; index++) {
156:       if (keys[index] === key) {
157:         return bag[keys[index]];
158:       }
159:     }
160:     return undefined;
161:   }
