163:   /**
164:    * The state handed to the store wins over the persisted snapshot; anything it
165:    * does not mention keeps its persisted value. When nothing was handed in, the
166:    * snapshot that preferences wrote on the previous run is restored.
167:    */
168:   private static resolveRestoredState(input: SavedInput, persistedSnapshot: string): Record<string, Object> {
169:     const merged: Record<string, Object> = {};
170:     let restored: Record<string, Object> | undefined = undefined;
171:     const stored = LegacySavedStore.lookup(input.persistence, PREFERENCE_SNAPSHOT_KEY);
172:     if (stored !== undefined) {
173:       restored = LegacySavedStore.asRecord(stored);
174:     }
175:     if (restored === undefined && persistedSnapshot.length > 0) {
176:       restored = LegacySavedStore.asRecordFromText(persistedSnapshot);
177:     }
178:     if (restored !== undefined) {
179:       const keys: string[] = Object.keys(restored);
180:       for (let index = 0; index < keys.length; index++) {
181:         merged[keys[index]] = restored[keys[index]];
182:       }
183:     }
184:     const keys: string[] = Object.keys(input.state);
185:     for (let index = 0; index < keys.length; index++) {
186:       merged[keys[index]] = input.state[keys[index]];
187:     }
188:     return merged;
189:   }
