191:   private static asRecord(value: Object): Record<string, Object> | undefined {
192:     const text: string = JSON.stringify(value);
193:     if (text.length < 2 || text.charAt(0) !== '{') {
194:       return undefined;
195:     }
196:     return JSON.parse(text) as Record<string, Object>;
197:   }
