199:   private static asRecordFromText(text: string): Record<string, Object> | undefined {
200:     if (text.length < 2 || text.charAt(0) !== '{') {
201:       return undefined;
202:     }
203:     return JSON.parse(text) as Record<string, Object>;
204:   }
