206:   private persistSnapshot(): void {
207:     const state = this.viewModel.currentState();
208:     const encoded = SavedSnapshotCodec.encode(this.database, state, this.mediaStatus.offlineArticleIdentities(),
209:       this.progressProjection());
210:     const sortModes: PersistedSortModes = new PersistedSortModes(state.articleSortMode, state.collectionSortMode);
211:     this.persistence['snapshot'] = encoded;
212:     this.persistence['saved_database_snapshot'] = encoded;
213:     this.persistence[PREFERENCE_SNAPSHOT_KEY] = encoded;
214:     this.persistence['persistedSortModes'] = JSON.parse(JSON.stringify(sortModes)) as Record<string, Object>;
215:     this.persistence[PREFERENCE_ARTICLE_SORT_MODE] = String(state.articleSortMode);
216:     this.persistence[PREFERENCE_COLLECTION_SORT_MODE] = String(state.collectionSortMode);
217:     this.persistence[PREFERENCE_LAST_TAB] = state.selectedTab;
218:     this.persistence[PREFERENCE_SYNC_ENABLED] = state.readingListSyncEnabled ? 'true' : 'false';
219:     this.persistence[PREFERENCE_DATABASE_SNAPSHOT] = encoded;
220:     this.writeThrough();
221:   }
222: 
223:   private progressProjection(): Record<string, number> {
224:     const projection: Record<string, number> = {};
225:     const identities = this.mediaStatus.downloadingIdentities();
226:     for (let index = 0; index < identities.length; index++) {
227:       projection[identities[index]] = this.mediaStatus.downloadProgress(identities[index]);
228:     }
229:     return projection;
230:   }
231: 
232:   private writeThrough(): void {
233:     const state = this.viewModel.currentState();
234:     const fingerprint: string = state.articleSortMode + '|' + state.collectionSortMode + '|' + state.selectedTab + '|'
235:       + String(state.readingListSyncEnabled);
236:     if (fingerprint === this.lastWriteFingerprint) {
237:       return;
238:     }
239:     this.lastWriteFingerprint = fingerprint;
240:     this.preferences.setArticleSortMode(state.articleSortMode);
241:     this.preferences.setCollectionSortMode(state.collectionSortMode);
242:     this.preferences.setLastTab(state.selectedTab);
243:     this.preferences.setSyncEnabled(state.readingListSyncEnabled);
244:     this.preferences.persistSnapshot(String(this.persistence[PREFERENCE_SNAPSHOT_KEY]));
245:   }
