1: /**
2:  * Minimal reactive stream used by the reading list data layer.
3:  *
4:  * The database exposes a change flow; derived queries subscribe to it and push
5:  * freshly projected values to their own collectors. This is what lets the Saved
6:  * page update when the underlying membership tables change without anybody
7:  * rebuilding the page by hand.
8:  */
9: export type FlowCallback<T> = (value: T) => void;
10: 
11: export class Flow<T> {
12:   private current: T;
13:   private readonly callbacks: FlowCallback<T>[] = [];
14: 
15:   constructor(initial: T) {
16:     this.current = initial;
17:   }
18: 
19:   getValue(): T {
20:     return this.current;
21:   }
22: 
23:   /**
24:    * Registers a collector and immediately replays the latest value so that a
25:    * late subscriber never misses the current snapshot.
26:    */
27:   collect(callback: FlowCallback<T>): void {
28:     this.callbacks.push(callback);
29:     callback(this.current);
30:   }
31: 
