67:     this.project(owner.state());
68:   }
69: 
70:   aboutToDisappear(): void {
71:     this.store?.closeSavedSurface();
72:   }
73: 
74:   private project(state: SavedUiState): void {
75:     this.selectedTab = state.selectedTab;
76:     this.articleRows = state.articleRows;
77:     this.collectionRows = state.collectionRows;
78:     this.selectedRowIds = state.selectedRowIds;
79:     this.selectionEnabled = state.selectionEnabled;
80:     this.searchQuery = state.searchQuery;
81:     this.isRefreshing = state.isRefreshing;
82:     this.emptyState = state.emptyState;
83:     this.onboarding = state.onboarding;
84:     this.badgeCount = state.badgeCount;
85:     this.feedbackMessage = state.feedback.visible ? state.feedback.message : '';
86:     this.feedbackAction = state.feedback.actionLabel;
87:     this.feedbackSeverity = state.feedback.severity;
88:     this.showSheet = state.saveSheet !== null && state.saveSheet.visible;
89:   }
