91:   /* -------------------------------------------------------------------- */
92:   /* Navigation                                                             */
93:   /* -------------------------------------------------------------------- */
94: 
95:   private selectTab(tab: string): void {
96:     this.store?.selectSavedTab(tab);
97:   }
