99:   private openSheetFor(row: SavedArticleRow): void {
100:     const pageTitle = new PageTitle(row.language, row.apiTitle, row.displayTitle);
101:     this.sheetParams = this.store !== undefined ? openSaveArticleSheetDialog(pageTitle, this.store) : undefined;
102:     this.showSheet = true;
103:     this.store?.openSaveArticleSheet();
104:   }
