106:   /* -------------------------------------------------------------------- */
107:   /* Build                                                                  */
108:   /* -------------------------------------------------------------------- */
109: 
110:   build() {
111:     Stack() {
112:       Column() {
113:         this.buildToolbar()
114:         this.buildSearchField()
115:         this.buildTabBar()
116:         this.buildSelectionBar()
117:         Refresh({ refreshing: $$this.isRefreshing }) {
118:           List() {
119:             if (this.selectedTab === TAB_ALL_ARTICLES) {
120:               this.buildArticleRows()
121:             } else {
122:               this.buildCollectionRows()
123:             }
124:             this.buildEmptyState()
125:             this.buildOnboarding()
126:             this.buildFeedback()
127:           }
128:           .layoutWeight(1)
129:           .width('100%')
130:         }
131:         .layoutWeight(1)
132:         .width('100%')
133:         .onRefreshing(() => {
134:           this.store?.retryPullToRefreshAndCompleteSync();
135:         })
136:       }
137:       .width('100%')
138:       .height('100%')
139: 
140:       if (this.showSheet && this.sheetParams !== undefined) {
141:         Column() {
142:           SaveArticleSheetDialog({ params: this.sheetParams })
143:         }
144:         .width('100%')
145:         .padding(16)
146:         .backgroundColor(Color.White)
147:         .borderRadius(12)
148:         .margin({ left: 12, right: 12, bottom: 12 })
149:         .align(Alignment.Bottom)
150:       }
151:     }
152:     .width('100%')
153:     .height('100%')
154:   }
155: 
156:   @Builder
157:   buildToolbar() {
158:     Row({ space: 8 }) {
159:       Text('Saved')
160:         .fontSize(26)
161:         .fontWeight(FontWeight.Bold)
162:       if (this.badgeCount > 0) {
163:         Text(String(this.badgeCount))
164:           .fontSize(12)
165:           .fontColor(Color.White)
166:           .backgroundColor(Color.Red)
167:           .borderRadius(10)
168:           .padding({ left: 6, right: 6 })
169:       }
170:       Blank()
171:       Button(this.selectionEnabled ? 'Done' : 'Select')
172:         .onClick(() => {
173:           if (this.selectionEnabled) {
174:             this.store?.exitSelectionMode();
175:           } else {
176:             this.store?.enterSelectionMode();
177:           }
178:         })
179:     }
180:     .width('100%')
181:     .padding(12)
182:   }
183: 
184:   @Builder
185:   buildSearchField() {
186:     Row({ space: 8 }) {
187:       if (this.searchVisible) {
188:         TextInput({ text: this.searchQuery, placeholder: 'Search saved' })
189:           .layoutWeight(1)
190:           .onChange((value: string) => {
191:             // Production debounce: the query only applies after the delay.
192:             this.store?.enterSavedSearchQuery(value, 0);
193:           })
194:         Button('Clear')
195:           .onClick(() => {
196:             this.store?.enterSavedSearchQuery('', 0);
197:           })
198:       } else {
199:         Button('Search')
200:           .onClick(() => {
201:             this.searchVisible = true;
202:           })
203:       }
204:     }
205:     .width('100%')
206:     .padding({ left: 12, right: 12, bottom: 8 })
207:   }
208: 
209:   /**
210:    * Actions available while the active tab is in selection mode. The set of
211:    * actions depends on the row type of the active tab.
212:    */
213:   @Builder
214:   buildSelectionBar() {
215:     if (this.selectionEnabled) {
216:       Row({ space: 8 }) {
217:         Text(String(this.selectedRowIds.length) + ' selected')
218:           .fontSize(12)
219:           .layoutWeight(1)
220:         Button('Select all')
221:           .onClick(() => {
222:             this.store?.selectAllVisibleRows();
223:           })
224:         Button('Clear')
225:           .onClick(() => {
226:             this.store?.selectNone();
227:           })
228:         Button('Remove')
229:           .enabled(this.selectedRowIds.length > 0)
230:           .onClick(() => {
231:             this.store?.deleteSelectedRows();
232:           })
233:       }
234:       .width('100%')
235:       .padding({ left: 12, right: 12, bottom: 8 })
236:     }
237:   }
238: 
239:   @Builder
240:   buildTabBar() {
241:     Column() {
242:       Row({ space: 8 }) {
243:         Button('All articles')
244:           .fontWeight(this.selectedTab === TAB_ALL_ARTICLES ? FontWeight.Bold : FontWeight.Normal)
245:           .onClick(() => {
246:             this.selectTab(TAB_ALL_ARTICLES);
247:           })
248:         Button('Collections')
249:           .fontWeight(this.selectedTab === TAB_COLLECTIONS ? FontWeight.Bold : FontWeight.Normal)
250:           .onClick(() => {
251:             this.selectTab(TAB_COLLECTIONS);
252:           })
253:       }
254:       .width('100%')
255: 
256:       if (this.selectedTab === TAB_ALL_ARTICLES) {
257:         Row({ space: 8 }) {
258:           Button(this.selectedFilterLabel())
259:             .onClick(() => {
260:               this.store?.selectArticleFilter(this.nextFilter());
261:             })
262:         }
263:         .width('100%')
264:         .padding({ top: 4 })
265:       } else {
266:         this.buildNewCollectionRow()
267:       }
268: 
269:       this.buildSortRow()
270:     }
271:     .width('100%')
272:     .padding({ left: 12, right: 12, bottom: 8 })
273:   }
274: 
275:   @Builder
276:   buildNewCollectionRow() {
277:     Row({ space: 8 }) {
278:       TextInput({ text: this.newCollectionTitle, placeholder: 'New collection name' })
279:         .layoutWeight(1)
280:         .onChange((value: string) => {
281:           this.newCollectionTitle = value;
282:         })
283:       Button('Create')
284:         .enabled(this.newCollectionTitle.trim().length > 0)
285:         .onClick(() => {
286:           this.store?.createCollection(this.newCollectionTitle);
287:           this.newCollectionTitle = '';
288:         })
289:     }
290:     .width('100%')
291:     .padding({ top: 4 })
292:   }
293: 
294:   @Builder
295:   buildSortRow() {
296:     Scroll() {
297:       Row({ space: 8 }) {
298:         ForEach(this.currentSortChoices(), (mode: number) => {
299:           Button(sortModeLabel(mode))
300:             .onClick(() => {
301:               this.store?.selectSortMode(mode);
302:             })
303:         }, (mode: number) => mode.toString())
304:       }
305:     }
306:     .scrollable(ScrollDirection.Horizontal)
307:     .scrollBar(BarState.Off)
308:     .width('100%')
309:     .margin({ top: 4 })
310:   }
311: 
312:   @Builder
313:   buildArticleRows() {
314:     ForEach(this.articleRows, (row: SavedArticleRow) => {
315:       Row({ space: 12 }) {
316:         if (this.selectionEnabled) {
317:           Checkbox({ name: row.id.toString(), group: 'saved-articles' })
318:             .select(this.selectedRowIds.indexOf(row.id) >= 0)
319:             .onChange(() => {
320:               this.store?.toggleRowSelection(row.id);
321:             })
322:         }
323:         Column({ space: 4 }) {
324:           Text(row.displayTitle)
325:             .fontSize(16)
326:           Text(row.collections.join(' · '))
327:             .fontSize(11)
328:           if (row.isOffline) {
329:             Text('Available offline')
330:               .fontSize(11)
331:           }
332:           if (row.downloadProgress >= 0) {
333:             Progress({ value: row.downloadProgress * 100, total: 100, type: ProgressType.Linear })
334:               .width('100%')
335:           }
336:         }
337:         .alignItems(HorizontalAlign.Start)
338:         .layoutWeight(1)
339:         Button('Save')
340:           .onClick(() => {
341:             this.openSheetFor(row);
342:           })
343:       }
344:       .width('100%')
345:       .padding(12)
346:     }, (row: SavedArticleRow) => row.id.toString())
347:   }
348: 
349:   @Builder
350:   buildCollectionRows() {
351:     ForEach(this.collectionRows, (row: SavedCollectionRow) => {
352:       Row({ space: 12 }) {
353:         if (this.selectionEnabled) {
354:           Checkbox({ name: row.id.toString(), group: 'saved-collections' })
355:             .select(this.selectedRowIds.indexOf(row.id) >= 0)
356:             .onChange(() => {
357:               this.store?.toggleRowSelection(row.id);
358:             })
359:         }
360:         Column({ space: 4 }) {
361:           Text(row.title)
362:             .fontSize(16)
363:           Text(String(row.articleCount) + ' articles')
364:             .fontSize(11)
365:         }
366:         .alignItems(HorizontalAlign.Start)
367:         .layoutWeight(1)
368:         Button('Delete')
369:           .enabled(row.deletable)
370:           .onClick(() => {
371:             this.store?.deleteCollection(row.id);
372:           })
373:       }
374:       .width('100%')
375:       .padding(12)
376:     }, (row: SavedCollectionRow) => row.id.toString())
377:   }
378: 
