380:   buildEmptyState() {
381:     if (this.emptyState !== EMPTY_STATE_NONE) {
382:       Column({ space: 8 }) {
383:         Text(this.emptyTitle())
384:           .fontSize(16)
385:           .fontWeight(FontWeight.Bold)
386:         Text(this.emptyMessage())
387:           .fontSize(12)
388:         Button(this.emptyRecoveryLabel())
389:           .onClick(() => {
390:             this.recoverFromEmptyState();
