398: 
399:   @Builder
400:   buildOnboarding() {
401:     if (this.onboarding !== ONBOARDING_NONE) {
402:       Row({ space: 8 }) {
403:         Text(this.onboardingMessage())
404:           .fontSize(12)
405:           .layoutWeight(1)
406:         Button(this.onboardingAction())
