440:   /* -------------------------------------------------------------------- */
441:   /* Derived helpers                                                        */
442:   /* -------------------------------------------------------------------- */
443: 
444:   private currentFilter(): string {
445:     const state: SavedUiState | undefined = this.store?.state();
446:     return state !== undefined ? state.selectedArticleFilter : ARTICLE_FILTER_ALL_ARTICLES;
447:   }
448: 
449:   private selectedFilterLabel(): string {
450:     return this.currentFilter() === ARTICLE_FILTER_NOT_IN_COLLECTION
451:       ? 'Filter: only in Saved' : 'Filter: all saved';
452:   }
453: 
454:   private nextFilter(): string {
455:     return this.currentFilter() === ARTICLE_FILTER_ALL_ARTICLES
456:       ? ARTICLE_FILTER_NOT_IN_COLLECTION : ARTICLE_FILTER_ALL_ARTICLES;
457:   }
458: 
459:   private currentSortChoices(): number[] {
460:     const state: SavedUiState | undefined = this.store?.state();
461:     if (state === undefined) {
462:       return COLLECTION_SORT_CHOICES;
463:     }
464:     return state.selectedTab === TAB_COLLECTIONS ? state.collectionSortChoices : state.articleSortChoices;
465:   }
466: 
467:   private emptyTitle(): string {
468:     if (this.emptyState === EMPTY_STATE_SEARCH_NO_RESULTS) {
469:       return 'No results';
470:     }
471:     if (this.emptyState === EMPTY_STATE_NOTHING_SELECTED) {
472:       return 'Nothing selected';
473:     }
474:     if (this.emptyState === EMPTY_STATE_NO_COLLECTIONS) {
475:       return 'No collections yet';
476:     }
477:     return 'Nothing saved yet';
478:   }
479: 
480:   private emptyMessage(): string {
481:     if (this.emptyState === EMPTY_STATE_SEARCH_NO_RESULTS) {
482:       return 'No saved item matches this search in this view.';
483:     }
484:     if (this.emptyState === EMPTY_STATE_NOTHING_SELECTED) {
485:       return 'Select a row to run an action on it.';
486:     }
487:     if (this.emptyState === EMPTY_STATE_NO_COLLECTIONS) {
488:       return 'Create a collection from the Collections tab or while saving an article.';
489:     }
490:     return 'Save an article to see it here.';
491:   }
492: 
493:   private emptyRecoveryLabel(): string {
494:     if (this.emptyState === EMPTY_STATE_SEARCH_NO_RESULTS) {
495:       return 'Clear search';
496:     }
497:     if (this.emptyState === EMPTY_STATE_NOTHING_SELECTED) {
498:       return 'Select all';
499:     }
500:     if (this.emptyState === EMPTY_STATE_NO_COLLECTIONS) {
501:       return 'Open All articles';
502:     }
503:     return 'Open Collections';
504:   }
505: 
506:   private recoverFromEmptyState(): void {
507:     if (this.emptyState === EMPTY_STATE_SEARCH_NO_RESULTS) {
508:       this.store?.enterSavedSearchQuery('', 0);
509:       return;
510:     }
511:     if (this.emptyState === EMPTY_STATE_NOTHING_SELECTED) {
512:       this.store?.selectAllVisibleRows();
513:       return;
514:     }
515:     if (this.emptyState === EMPTY_STATE_NO_ARTICLES) {
516:       this.selectTab(TAB_COLLECTIONS);
517:       return;
518:     }
519:     this.selectTab(TAB_ALL_ARTICLES);
520:   }
521: 
522:   private onboardingMessage(): string {
523:     if (this.onboarding === ONBOARDING_SYNC_REMINDER) {
524:       return 'Sync your reading lists to keep them on all your devices.';
525:     }
526:     if (this.onboarding === ONBOARDING_LOGIN_REMINDER) {
527:       return 'Log in to synchronise your reading lists.';
528:     }
529:     if (this.onboarding === ONBOARDING_SHARED_COLLECTION) {
530:       return 'A collection was shared with you.';
531:     }
532:     return '';
533:   }
534: 
535:   private onboardingAction(): string {
536:     if (this.onboarding === ONBOARDING_SYNC_REMINDER) {
537:       return 'Sync now';
538:     }
539:     if (this.onboarding === ONBOARDING_LOGIN_REMINDER) {
540:       return 'Log in';
541:     }
542:     return 'Open';
543:   }
544: 
545:   private runOnboardingAction(): void {
546:     if (this.onboarding === ONBOARDING_SYNC_REMINDER) {
547:       this.store?.retryPullToRefreshAndCompleteSync();
548:       return;
549:     }
550:     if (this.onboarding === ONBOARDING_LOGIN_REMINDER) {
551:       this.store?.onLoginEvent('', false);
552:       return;
553:     }
554:     this.selectTab(TAB_COLLECTIONS);
555:   }
556: }
